import itertools

def solve():
    n, k = map(int, input().split())
    ans = 0
    opinions = [input().strip() for _ in range(n)]

    for r in range(1, n+1):
        for subset in itertools.combinations(range(n), r):
            yes = sum(1 for i in subset for j, c in enumerate(opinions[i]) if c == '+')
            no = r - yes
            if yes > no:
                if all(any(c == '-' for c in opinions[i] if i in subset) for i in range(n)):
                    continue
            elif yes < no:
                if all(any(c == '+' for c in opinions[i] if i in subset) for i in range(n)):
                    continue
            else:
                if all(any(c == '+' for c in opinions[i] for i in subset) or any(c == '-' for c in opinions[i] for i in subset) for i in range(n)):
                    continue
            ans = max(ans, r+1)
    print(ans)

