def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        nums = list(map(int, input().split()))

        even_sum = 0
        odd_sum = 0
        for num in nums:
            if num % 2 == 0:
                even_sum += num
            else:
                odd_sum += num

        even_deque = deque()
        odd_deque = deque()
        for num in nums:
            if num % 2 == 0:
                even_deque.append(num)
            else:
                odd_deque.append(num)

        while odd_sum <= even_sum:
            if not even_deque:
                break
            if odd_sum >= even_sum and len(odd_deque) > 1:
                odd_sum += odd_deque.popleft()
