def solve():
    n = int(input())
    a = list(map(int, input().split()))
    factors = []
    for i in range(n):
        factors.append((a[i], 1))
    for i in range(2, int(math.sqrt(max(a)) + 1)):
        for j in range(n):
            while a[j] % i == 0:
                factors[j] = (factors[j][0] // i, factors[j][1] + 1)
                a[j] //= i
        for j in range(n):
            while a[j] % i == 0:
                factors[j] = (factors[j][0] // i, factors[j][1] + 1)
                a[j] //= i
    product = reduce(lambda x, y: x * y[0]**y[1], factors, 1)
    return product * 2022

