        min_prefix[i] = min(min_prefix[i - 1], a[i - 1])

    for i in range(n - 1, 0, -1):
        min_suffix[i] = min(min_suffix[i + 1], a[i])

    max_sum = 0
    for i in range(1, n):
        max_sum = max(max_sum, max_suffix[i + 1] - min_suffix[i + 1] + max_prefix[i] - min_prefix[i])

