            print(0)
        else:
            points.sort()
            heapq.heapify(points)
            curr_x, curr_y = 0, 0
            ans = 0
            while points:
                _, x = heapq.heappop(points)
                if curr_x < x:
                    curr_x += 1
                elif curr_x > x:
                    curr_x -= 1
                curr_y = max(curr_y, x)
                ans += abs(curr_x - x)
            ans *= 2
            curr_x, curr_y = 0, 0
            while points:
                _, y = heapq.heappop(points)
                if curr_y < y:
                    curr_y += 1
                elif curr_y > y:
                    curr_y -= 1
                curr_x = max(curr_x, y)
                ans += abs(curr_y - y)
            ans -= 2 * max(abs(curr_x), abs(curr_y))
            print(ans)

