from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = list(input())
        b = list(input())
        if n < m:
            print("NO")
            continue
        a = deque(a)
        b = deque(b)
        a.reverse()
        b.reverse()
        last_a, last_b = a.pop(), b.pop()
        for i in range(n - m + 1):
            if last_a == last_b:
                if a and a[-1] == last_a:
                    last_a = a.pop()
                    last_b = b.pop()
                else:
                    break
            elif a[-1] == '0':
                a.pop()
                last_a = a.pop()
                last_b = b.pop()
            else:
                a.pop()
                last_a = a.pop()
                last_b = b.pop()
        if not b:
            print("YES")
        else:
            print("NO")

