def solve():
    for _ in range(int(input())):
        n = int(input())
        a = list(map(int, input().split()))
        moves = [deque(input().replace(" ", "") for _ in range(n)]

        for i in range(n):
            moves[i] = [1 if move == "U" else -1 for move in moves[i]]
            moves[i].append(0)
            for j in range(len(moves[i]) - 1):
                moves[i][j] += moves[i][j + 1]
            for j in range(len(moves[i]) - 2, -1, -1):
                moves[i][j] = (moves[i][j] + moves[i][j + 1]) % 10

        for i in range(n):
            a[i] = (a[i] + moves[i][-1]) % 10
            for j in range(len(moves[i]) - 2, -1, -1):
                a[i] -= moves[i][j]
            print(a[i], end=" ")
        print()

