from functools import lru_cache
import sys

def solve():
    n, m = map(int, input().split())
    @lru_cache(None)
    def dp(x, y):
        if x == n:
            return y * (n - 1) + m
        if y == m:
            return x * m + (m - 1)
        return min(dp(x + 1, y) + y * (n - x), dp(x, y + 1) + x * m)
    print(dp(1, 1))

